/** A replacement function cannot inherit builtin totality in MINUS rewrites. */
@Isolated
class LmdbSketchFunctionOverrideTest {

	@Test
	void throwingContainsReplacementCannotBecomeOuterNegation() {
		Function replacement = throwingContains();
		FunctionRegistry registry = FunctionRegistry.getInstance();
		Function previous = registry.add(replacement).orElse(null);
		try {
			ValueFactory vf = SimpleValueFactory.getInstance();
			StatementPattern pattern = new StatementPattern(new Var("s"), new Var("p", vf.createIRI("urn:test:p")),
					new Var("o"));
			FunctionCall condition = new FunctionCall(FN.CONTAINS.stringValue(), new Str(new Var("s")),
					new ValueConstant(vf.createLiteral("x")));
			QueryRoot root = new QueryRoot(new Difference(pattern, new Filter(pattern.clone(), condition)));
			new LmdbSketchJoinOptimizer(new EvaluationStatistics(), false).optimize(root, null, null);
			assertInstanceOf(Difference.class, root.getArg(),
					"an error in the RHS filter retains the LHS; an outer NOT(error) would remove it");
		} finally {
			registry.remove(replacement);
			if (previous != null) {
				registry.add(previous);
			}
		}
	}

	@Test
	void minusWithThrowingReplacementMatchesMemoryStore(@TempDir Path directory) {
		Function replacement = throwingContains();
		FunctionRegistry registry = FunctionRegistry.getInstance();
		Function previous = registry.add(replacement).orElse(null);
		SailRepository memory = new SailRepository(new MemoryStore());
		LmdbStore store = new LmdbStore(directory.toFile());
		store.setExperimentalQueryOptimizations(true);
		SailRepository lmdb = new SailRepository(store);
		try {
			memory.init();
			lmdb.init();
			for (SailRepository repository : new SailRepository[] { memory, lmdb }) {
				try (var connection = repository.getConnection()) {
					ValueFactory vf = connection.getValueFactory();
					connection.add(vf.createIRI("urn:test:a"), vf.createIRI("urn:test:p"), vf.createLiteral("x"));
					connection.add(vf.createIRI("urn:test:b"), vf.createIRI("urn:test:p"), vf.createLiteral("y"));
				}
			}
			String query = "SELECT ?s WHERE { ?s <urn:test:p> ?o MINUS { ?s <urn:test:p> ?o "
					+ "FILTER(CONTAINS(STR(?s), 'x')) } }";
			assertEquals(2, countRows(memory, query));
			assertEquals(2, countRows(lmdb, query));
		} finally {
			lmdb.shutDown();
			memory.shutDown();
			registry.remove(replacement);
			if (previous != null) {
				registry.add(previous);
			}
		}
	}

	private static int countRows(SailRepository repository, String query) {
		try (var connection = repository.getConnection(); var result = connection.prepareTupleQuery(query).evaluate()) {
			int count = 0;
			while (result.hasNext()) {
				result.next();
				count++;
			}
			return count;
		}
	}

	private static Function throwingContains() {
		return new Function() {
			@Override
			public String getURI() {
				return FN.CONTAINS.stringValue();
			}

			@Override
			public Value evaluate(ValueFactory valueFactory, Value... args) {
				throw new ValueExprEvaluationException("intentional replacement error");
			}

			@Override
			public Determinism getDeterminism() {
				return Determinism.DETERMINISTIC;
			}
		};
	}
}
